//! Module for treating situations when the problem generated by [`SolverModel`](super::SolverModel) is infeasible.
//! In such case we try to obtain the IIS (irreducible infeasible subsystem), and explain it to the user.
//! We take all the constraints of IIS and rephrase them with natural language.
//! The final explanation is written to `.duck_sync/iis_expl.txt` in the root package's directory
//! (see `AnyPackage::iis_expl_path`).
//!
//! Note
//! ----
//! Because precisely describing a package can be very lengthy (it requires an URL),
//! in the explanation we refer to the root package by `root package` and
//! default registry packages by name and version while all the other packages get an index
//! and are referred to with `#<index>`.
//! Below list of constraints, the file contains a translation from indexes to descriptions of packages.

use std::collections::{HashMap, HashSet};
use std::ffi::CStr;
use std::path::Path;

use russcip::{Model, Retcode, Solved, ffi};

use crate::core::PackageId;
use crate::core::full_identity::FullKind;
use crate::core::solver::solving::solver_model::Constraint;
use crate::util::Pluralize;
use crate::util::filesystem::{touch, write_file};
use crate::util::interning::QpJoin;
use crate::{DuckContext, QuackResult, QuackResultContext, StrId, qp_bail, qp_bail_internal};

/// Finds the IIS, generates its explanation and writes it into the file pointed by `path`.
pub fn generate_iis_explanation(
    model: &Model<Solved>,
    root: PackageId,
    constraints: Vec<Constraint>,
    ctx: &DuckContext,
    path: &Path,
) -> QuackResult<()> {
    // Get constraint names and turn them into indexes.
    let iis_constraint_idxs = iis_constraint_names(model)
        .context("failed to obtain IIS constraint names")?
        .into_iter()
        .map(|name| {
            name.parse::<usize>()
                .with_context_internal(|| format!("constraint name `{name}` is not a valid number"))
        })
        .collect::<QuackResult<HashSet<usize>>>()?;
    // Create empty IISExplainer.
    let mut explainer = IISExplainer::new(root);
    // Register constraints.
    for (idx, constraint) in constraints.into_iter().enumerate() {
        if iis_constraint_idxs.contains(&idx) {
            explainer.register_constraint(constraint, ctx)?;
        }
    }
    // Get the final explanation.
    let explanation = explainer.generate_explanation();
    touch(path).with_context(|| {
        format!(
            "failed to create the IIS explanation file at `{}`",
            path.display()
        )
    })?;
    write_file(path, explanation).with_context(|| {
        format!(
            "failed to write the IIS explanation to `{}`",
            path.display()
        )
    })?;
    Ok(())
}

/// Computes an irreducible infeasible subsystem (IIS) of an infeasible model and returns the names
/// of its constraints.
fn iis_constraint_names(model: &Model<Solved>) -> QuackResult<Vec<String>> {
    let scip = model.scip_ptr();
    // SAFETY: `scip` lives as long as `model`. The IIS and its sub-SCIP are owned by `scip`, and
    // the constraint names are copied out before we return.
    unsafe {
        let retcode = Retcode::from(ffi::SCIPgenerateIIS(scip));
        if retcode != Retcode::Okay {
            qp_bail!(
                "obtaining IIS for the dependency problem failed; SCIP's retcode is {retcode:?}"
            );
        }
        let iis = ffi::SCIPgetIIS(scip);
        if ffi::SCIPiisIsSubscipInfeasible(iis) == 0 {
            qp_bail_internal!("`SCIPgetIIS` did not return an IIS");
        }
        let subscip = ffi::SCIPiisGetSubscip(iis);
        let n_conss = ffi::SCIPgetNOrigConss(subscip) as usize;
        if n_conss == 0 {
            qp_bail_internal!("the IIS has no constraints");
        }
        let conss = std::slice::from_raw_parts(ffi::SCIPgetOrigConss(subscip), n_conss);
        Ok(conss
            .iter()
            .map(|&cons| {
                CStr::from_ptr(ffi::SCIPconsGetName(cons))
                    .to_string_lossy()
                    .into_owned()
            })
            .collect())
    }
}

/// Struct devoted to generating the explanation of the IIS.
struct IISExplainer {
    /// Root package of the problem.
    root_pkg: PackageId,
    /// Explanations generated for each constraints.
    constraint_explanations: Vec<String>,
    /// Explanations generated for each non root, non default registry package.
    package_explanations: Vec<String>,
    /// Indexes with which non root, non default registry packages are referred to.
    /// This is always the same as the index of the package in [`Self::package_explanations`].
    packages_to_idxs: HashMap<PackageId, usize>,
}

impl IISExplainer {
    /// Create a new [`IISExplainer`].
    fn new(root_pkg: PackageId) -> Self {
        Self {
            root_pkg,
            constraint_explanations: vec![],
            package_explanations: vec![],
            packages_to_idxs: HashMap::new(),
        }
    }

    /// Generate the full explanation of the IIS.
    /// The explanation consists of two parts.
    /// The first part lists all the constraints of the IIS,
    /// while the second part describes the packages referred to in the first part.
    /// If IIS constraints refer to only root or default registry packages, the second part is omitted.
    fn generate_explanation(self) -> String {
        let packages_expl = if self.package_explanations.is_empty() {
            "".to_string()
        } else {
            format!("\n\nWhere:\n{}", self.package_explanations.join("\n"))
        };
        format!(
            "The following constraints are mutually infeasible:\n\n{}{packages_expl}",
            self.constraint_explanations.join("\n\n")
        )
    }

    /// For a given constraint, generates and stores the message explaining it.
    fn register_constraint(
        &mut self,
        constraint: Constraint,
        ctx: &DuckContext,
    ) -> QuackResult<()> {
        let explanation = match constraint {
            Constraint::RequireRootPackage => "root package must be in the solution".to_string(),
            Constraint::RequireRootFeature(f) => {
                format!("root package's feature `{f}` must be present in the solution")
            }
            Constraint::ForbidPackageBecauseNoRealization { pkg, dep_dname } => format!(
                "no realization of dependency `{dep_dname}` for {} found; package must not be present in the solution",
                self.refer_to_pkg(pkg, ctx)?
            ),
            Constraint::ForbidPackageFeaturesBecauseNoRealization {
                pkg,
                dep_dname,
                feature,
            } => format!(
                "no realization of dependency `{dep_dname}` enabled by `{feature}` for {} found; package with feature must not be present in the solution",
                self.refer_to_pkg(pkg, ctx)?
            ),
            Constraint::ForbidFeatureBecauseForces {
                pkg,
                dep_dname,
                enabling_feature,
                forcing_feature,
                realization,
            } => {
                let features = enabling_and_forcing_to_vec(enabling_feature, forcing_feature);
                format!(
                    "dependency `{dep_dname}` of {}{} forces a feature unsupported by potential realization: {}; the latter package cannot be a realization in such case",
                    self.refer_to_pkg(pkg, ctx)?,
                    if features.is_empty() {
                        String::new()
                    } else {
                        format!(
                            " with feature{} `{}`",
                            features.s_if_plural(),
                            features.join("`, `")
                        )
                    },
                    self.refer_to_pkg(realization, ctx)?
                )
            }
            Constraint::ForbidPreexistingFeatureBecauseForces {
                pkg,
                dep_dname,
                realization,
                feature,
            } => format!(
                "dependency `{dep_dname}` of previous freeze {} with `{feature}` forces a feature unsupported by the previous freeze realization: {}; the package must not be present with the feature",
                self.refer_to_pkg(pkg, ctx)?,
                self.refer_to_pkg(realization, ctx)?,
            ),
            Constraint::RequireDepRealization {
                dep,
                parent_feature,
                realizations,
            } => format!(
                "dependency `{}` of {}{} must be realized by {}; if the package is present, then one realization must be as well",
                dep.dep_ename,
                self.refer_to_pkg(dep.parent, ctx)?,
                if let Some(f) = parent_feature {
                    format!(" with feature `{f}`")
                } else {
                    String::new()
                },
                realizations
                    .into_iter()
                    .map(|pkg| self.refer_to_pkg(pkg, ctx))
                    .collect::<QuackResult<Vec<String>>>()?
                    .join(" or ")
            ),
            Constraint::RequireForcedFeature {
                dep,
                enabling_feature,
                forcing_feature,
                realization,
                forced_features,
            } => {
                let forcing_features =
                    enabling_and_forcing_to_vec(enabling_feature, forcing_feature);
                format!(
                    "dependency `{}` of {}{} forces feature{} `{}` on a possible realization: {}; the realization (if chosen) must have those features",
                    dep.dep_ename,
                    self.refer_to_pkg(dep.parent, ctx)?,
                    if forcing_features.is_empty() {
                        String::new()
                    } else {
                        format!(
                            " with feature{} `{}`",
                            forcing_features.s_if_plural(),
                            forcing_features.join("`, `")
                        )
                    },
                    forced_features.s_if_plural(),
                    forced_features.join("`, `"),
                    self.refer_to_pkg(realization, ctx)?
                )
            }
            Constraint::RequireForcedFeatureForPreexisting {
                parent,
                parent_feature,
                dep_dname,
                realization,
                forced_features,
            } => format!(
                "dependency `{}` of previous freeze {} with a not previous freeze feature `{parent_feature}` forces feature{} `{}` of the previous freeze realization: {}; the realization must have those features, if parent has the forcing one",
                dep_dname,
                self.refer_to_pkg(parent, ctx)?,
                forced_features.s_if_plural(),
                forced_features.join("`, `"),
                self.refer_to_pkg(realization, ctx)?
            ),
            Constraint::RequireFeatureExpansion {
                pkg,
                feature,
                expands_to,
            } => format!(
                "feature `{feature}` of {} expands to feature{} `{}`; if the expanding feature is present, all the other must be as well",
                self.refer_to_pkg(pkg, ctx)?,
                expands_to.s_if_plural(),
                expands_to.join("`, `")
            ),
            Constraint::ForbidMultipleVersions { versions } => format!(
                "{} all have the same identity; at most one of them can be present",
                versions
                    .into_iter()
                    .map(|pkg| self.refer_to_pkg(pkg, ctx))
                    .collect::<QuackResult<Vec<String>>>()?
                    .join(" and ")
            ),
            Constraint::ForbidDifferentVersions {
                different_versions,
                preexistent_version,
            } => {
                let text = if different_versions.len() < 2 {
                    "has the same identity as"
                } else {
                    "all have the same identity as"
                };
                format!(
                    "{} {} {}; only the previous freeze version can be present",
                    different_versions
                        .into_iter()
                        .map(|pkg| self.refer_to_pkg(pkg, ctx))
                        .collect::<QuackResult<Vec<String>>>()?
                        .join(" and "),
                    text,
                    self.refer_to_pkg(preexistent_version, ctx)?
                )
            }
        };
        self.constraint_explanations.push(explanation);
        Ok(())
    }

    /// Determines how the package should be referred to in an explanation of a constraint.
    /// The root package and default registry packages are named naturally.
    /// Other packages are given identifiers, to not complicate the constraint messages with long package descriptions.
    fn refer_to_pkg(&mut self, pkg: PackageId, ctx: &DuckContext) -> QuackResult<String> {
        if pkg == self.root_pkg {
            Ok("root package".to_string())
        } else if pkg.is_default_registry(ctx)? {
            Ok(format!("package `{}@{}`", pkg.name(), pkg.version()))
        } else {
            let idx = self.register_pkg(pkg);
            Ok(format!("package `#{idx}`"))
        }
    }

    /// Adds information to [`IISExplainer`] about a non root, non default registry package.
    /// Returns the index with which the package is referred to.
    fn register_pkg(&mut self, pkg: PackageId) -> usize {
        if let Some(idx) = self.packages_to_idxs.get(&pkg) {
            return *idx;
        }
        let idx = self.package_explanations.len();
        self.package_explanations
            .push(format!("#{idx}: {}", Self::explain_pkg(pkg)));
        self.packages_to_idxs.insert(pkg, idx);
        idx
    }

    /// Generates a unique description of a non root, non default registry package.
    fn explain_pkg(pkg: PackageId) -> String {
        match pkg.origin().kind() {
            FullKind::Local | FullKind::Registry => format!(
                "package `{}@{}` from `{}`",
                pkg.name(),
                pkg.version(),
                pkg.url()
            ),
            FullKind::Git { commit } => format!(
                "package `{}@{}` cloned from `{}` in commit `{commit}`",
                pkg.name(),
                pkg.version(),
                pkg.url()
            ),
        }
    }
}

/// Helper for [`IISExplainer::register_constraint`].
/// Turns two maybe features to a vector of features.
fn enabling_and_forcing_to_vec(enabling: Option<StrId>, forcing: Option<StrId>) -> Vec<StrId> {
    let mut features = vec![];
    if let Some(enabling) = enabling {
        features.push(enabling);
    }
    if let Some(forcing) = forcing {
        features.push(forcing);
    }
    features
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::*;
    use crate::core::Version;
    use crate::core::full_identity::{FullIdentity, FullOrigin};
    use crate::core::solver::dependency_edge::DependencyEdge;
    use crate::util::test_utils::duck_context_for_tests;
    use crate::util::to_url::ToUrl;

    /// The root package of every test: a local package `root@1.0.0`.
    fn root() -> PackageId {
        let origin = FullOrigin::for_local(Path::new("/projects/root")).unwrap();
        PackageId::new(
            FullIdentity::new("root".into(), origin),
            Version::new(1, 0, 0),
        )
    }

    /// A package from the default registry of `ctx`.
    fn registry_pkg(ctx: &DuckContext, name: &str, major: u64) -> PackageId {
        let origin = FullOrigin::for_registry(ctx.duck_cfg().registry_url().unwrap());
        PackageId::new(
            FullIdentity::new(name.into(), origin),
            Version::new(major, 0, 0),
        )
    }

    /// Registers `constraints` in a fresh [`IISExplainer`] and returns the whole explanation.
    fn explain(ctx: &DuckContext, constraints: Vec<Constraint>) -> String {
        let mut explainer = IISExplainer::new(root());
        for constraint in constraints {
            explainer.register_constraint(constraint, ctx).unwrap();
        }
        explainer.generate_explanation()
    }

    /// Prepends the header of the explanation to the expected constraint messages.
    fn expected(constraints: &str) -> String {
        format!("The following constraints are mutually infeasible:\n\n{constraints}")
    }

    #[test]
    /// [`Constraint::RequireRootPackage`]
    fn require_root_package() {
        let ctx = duck_context_for_tests();
        assert_eq!(
            explain(&ctx, vec![Constraint::RequireRootPackage]),
            expected("root package must be in the solution")
        );
    }

    #[test]
    /// [`Constraint::RequireRootFeature`]
    fn require_root_feature() {
        let ctx = duck_context_for_tests();
        assert_eq!(
            explain(&ctx, vec![Constraint::RequireRootFeature("fast".into())]),
            expected("root package's feature `fast` must be present in the solution")
        );
    }

    #[test]
    /// [`Constraint::ForbidPackageBecauseNoRealization`]
    fn forbid_package_because_no_realization() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidPackageBecauseNoRealization {
            pkg: registry_pkg(&ctx, "a", 1),
            dep_dname: "b".into(),
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "no realization of dependency `b` for package `a@1.0.0` found; \
                 package must not be present in the solution"
            )
        );
    }

    #[test]
    /// [`Constraint::ForbidPackageFeaturesBecauseNoRealization`]
    fn forbid_package_features_because_no_realization() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidPackageFeaturesBecauseNoRealization {
            pkg: registry_pkg(&ctx, "a", 1),
            dep_dname: "b".into(),
            feature: "fast".into(),
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "no realization of dependency `b` enabled by `fast` for package `a@1.0.0` found; \
                 package with feature must not be present in the solution"
            )
        );
    }

    #[test]
    /// [`Constraint::ForbidFeatureBecauseForces`]
    fn forbid_feature_because_forces() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidFeatureBecauseForces {
            pkg: registry_pkg(&ctx, "a", 1),
            dep_dname: "b".into(),
            enabling_feature: Some("with-b".into()),
            forcing_feature: Some("fast".into()),
            realization: registry_pkg(&ctx, "b", 2),
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "dependency `b` of package `a@1.0.0` with features `with-b`, `fast` forces a \
                 feature unsupported by potential realization: package `b@2.0.0`; the latter \
                 package cannot be a realization in such case"
            )
        );
    }

    #[test]
    /// [`Constraint::ForbidPreexistingFeatureBecauseForces`]
    fn forbid_preexisting_feature_because_forces() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidPreexistingFeatureBecauseForces {
            pkg: registry_pkg(&ctx, "a", 1),
            dep_dname: "b".into(),
            realization: registry_pkg(&ctx, "b", 2),
            feature: "fast".into(),
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "dependency `b` of previous freeze package `a@1.0.0` with `fast` forces a feature \
                 unsupported by the previous freeze realization: package `b@2.0.0`; the package \
                 must not be present with the feature"
            )
        );
    }

    #[test]
    /// [`Constraint::RequireDepRealization`]
    fn require_dep_realization() {
        let ctx = duck_context_for_tests();
        let pkg_a = registry_pkg(&ctx, "a", 1);
        let pkg_b1 = registry_pkg(&ctx, "b", 1);
        let pkg_b2 = registry_pkg(&ctx, "b", 2);
        let constraint = Constraint::RequireDepRealization {
            dep: DependencyEdge {
                parent: pkg_a,
                dep_identity: pkg_b1.identity(),
                dep_ename: "b".into(),
            },
            parent_feature: Some("with-b".into()),
            realizations: vec![pkg_b1, pkg_b2],
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "dependency `b` of package `a@1.0.0` with feature `with-b` must be realized by \
                 package `b@1.0.0` or package `b@2.0.0`; if the package is present, then one \
                 realization must be as well"
            )
        );
    }

    #[test]
    /// [`Constraint::RequireForcedFeature`]
    fn require_forced_feature() {
        let ctx = duck_context_for_tests();
        let pkg_b = registry_pkg(&ctx, "b", 2);
        let constraint = Constraint::RequireForcedFeature {
            dep: DependencyEdge {
                parent: registry_pkg(&ctx, "a", 1),
                dep_identity: pkg_b.identity(),
                dep_ename: "b".into(),
            },
            enabling_feature: None,
            forcing_feature: Some("fast".into()),
            realization: pkg_b,
            forced_features: vec!["simd".into(), "threads".into()],
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "dependency `b` of package `a@1.0.0` with feature `fast` forces features `simd`, \
                 `threads` on a possible realization: package `b@2.0.0`; the realization (if \
                 chosen) must have those features"
            )
        );
    }

    #[test]
    /// [`Constraint::RequireForcedFeatureForPreexisting`]
    fn require_forced_feature_for_preexisting() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::RequireForcedFeatureForPreexisting {
            parent: registry_pkg(&ctx, "a", 1),
            parent_feature: "fast".into(),
            dep_dname: "b".into(),
            realization: registry_pkg(&ctx, "b", 2),
            forced_features: vec!["simd".into()],
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "dependency `b` of previous freeze package `a@1.0.0` with a not previous freeze \
                 feature `fast` forces feature `simd` of the previous freeze realization: package \
                 `b@2.0.0`; the realization must have those features, if parent has the forcing \
                 one"
            )
        );
    }

    #[test]
    /// [`Constraint::RequireFeatureExpansion`]
    fn require_feature_expansion() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::RequireFeatureExpansion {
            pkg: registry_pkg(&ctx, "a", 1),
            feature: "full".into(),
            expands_to: vec!["fast".into(), "safe".into()],
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "feature `full` of package `a@1.0.0` expands to features `fast`, `safe`; if the \
                 expanding feature is present, all the other must be as well"
            )
        );
    }

    #[test]
    /// [`Constraint::ForbidMultipleVersions`]
    fn forbid_multiple_versions() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidMultipleVersions {
            versions: vec![registry_pkg(&ctx, "b", 1), registry_pkg(&ctx, "b", 2)],
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "package `b@1.0.0` and package `b@2.0.0` all have the same identity; at most one \
                 of them can be present"
            )
        );
    }

    #[test]
    /// [`Constraint::ForbidDifferentVersions`]
    fn forbid_different_versions() {
        let ctx = duck_context_for_tests();
        let constraint = Constraint::ForbidDifferentVersions {
            different_versions: vec![registry_pkg(&ctx, "b", 2)],
            preexistent_version: registry_pkg(&ctx, "b", 1),
        };
        assert_eq!(
            explain(&ctx, vec![constraint]),
            expected(
                "package `b@2.0.0` has the same identity as package `b@1.0.0`; only the previous \
                 freeze version can be present"
            )
        );
    }

    #[test]
    /// Packages which are neither the root nor from the default registry get an index in the
    /// constraint messages and are described in the `Where:` part, each one only once.
    fn non_default_registry_packages_are_described_below() {
        let ctx = duck_context_for_tests();
        let other_registry = "https://other-registry.example.com".to_url().unwrap();
        let other_pkg = PackageId::new(
            FullIdentity::new("b".into(), FullOrigin::for_registry(other_registry)),
            Version::new(2, 0, 0),
        );
        let git_url = "https://git.example.com/c.git".to_url().unwrap();
        let git_pkg = PackageId::new(
            FullIdentity::new("c".into(), FullOrigin::for_git(git_url, "abc123")),
            Version::new(3, 0, 0),
        );
        let local_pkg = PackageId::new(
            FullIdentity::new(
                "d".into(),
                FullOrigin::for_local(Path::new("/projects/d")).unwrap(),
            ),
            Version::new(4, 0, 0),
        );
        let registry_a = registry_pkg(&ctx, "a", 1);
        let constraints = vec![
            Constraint::RequireRootPackage,
            Constraint::ForbidMultipleVersions {
                versions: vec![other_pkg, git_pkg],
            },
            Constraint::ForbidPackageBecauseNoRealization {
                pkg: local_pkg,
                dep_dname: "e".into(),
            },
            Constraint::ForbidPreexistingFeatureBecauseForces {
                pkg: registry_a,
                dep_dname: "b".into(),
                realization: other_pkg,
                feature: "fast".into(),
            },
        ];
        assert_eq!(
            explain(&ctx, constraints),
            format!(
                "The following constraints are mutually infeasible:\n\n\
                 root package must be in the solution\n\n\
                 package `#0` and package `#1` all have the same identity; at most one of them \
                 can be present\n\n\
                 no realization of dependency `e` for package `#2` found; package must not be \
                 present in the solution\n\n\
                 dependency `b` of previous freeze package `a@1.0.0` with `fast` forces a feature \
                 unsupported by the previous freeze realization: package `#0`; the package must \
                 not be present with the feature\n\n\
                 Where:\n\
                 #0: package `b@2.0.0` from `{}`\n\
                 #1: package `c@3.0.0` cloned from `{}` in commit `abc123`\n\
                 #2: package `d@4.0.0` from `{}`",
                other_pkg.url(),
                git_pkg.url(),
                local_pkg.url(),
            )
        );
    }
}
